"""Small, self-contained implementation of chezmoi's default diff output."""
import difflib
import hashlib
import os
import stat


def _decode_path(rel):
    parts = []
    for part in rel.split(os.sep):
        if part.startswith("dot_"):
            part = "." + part[4:]
        elif part.startswith("private_"):
            part = part[8:]
        elif part.startswith("exact_"):
            part = part[6:]
        elif part.startswith("executable_"):
            part = part[11:]
        elif part.startswith("readonly_"):
            part = part[9:]
        parts.append(part)
    return os.path.join(*parts)


def _files(root):
    result = {}
    if not os.path.isdir(root):
        return result
    for base, dirs, names in os.walk(root):
        dirs[:] = [d for d in dirs if d not in (".git", ".chezmoiscripts")]
        for name in names:
            p = os.path.join(base, name)
            rel = os.path.relpath(p, root)
            if name.startswith(".chezmoi.") or name.endswith(".tmpl"):
                continue
            key = _decode_path(rel).replace(os.sep, "/")
            try:
                with open(p, "rb") as f:
                    data = f.read()
                mode = os.stat(p).st_mode
                result[key] = (data, mode)
            except OSError:
                pass
    return result


def run(source, destination, targets=None, reverse=False):
    """Print unified git-style diffs; return status code."""
    src, dst = _files(source), _files(destination)
    if targets:
        selected = set()
        for target in targets:
            target = os.path.expanduser(target).replace(os.sep, "/")
            if target.startswith(destination.rstrip("/") + "/"):
                target = target[len(destination.rstrip("/")) + 1:]
            selected.add(target.lstrip("/"))
        keys = [k for k in sorted(src.keys() | dst.keys()) if k in selected]
    else:
        keys = sorted(src.keys() | dst.keys())
    out = []
    for key in keys:
        a = dst.get(key)
        b = src.get(key)
        if reverse:
            a, b = b, a
        if a and b and a[0] == b[0] and (a[1] & 0o777) == (b[1] & 0o777):
            continue
        old = a[0] if a else b""
        new = b[0] if b else b""
        oldhash = hashlib.sha1(old).hexdigest() if a else "0" * 40
        newhash = hashlib.sha1(new).hexdigest() if b else "0" * 40
        out.append(f"diff --git a/{key} b/{key}\n")
        if not a:
            out.append(f"new file mode {stat.S_IMODE(b[1]):06o}\n")
        elif not b:
            out.append(f"deleted file mode {stat.S_IMODE(a[1]):06o}\n")
        out.append(f"index {oldhash}..{newhash} 100644\n")
        oldlines = old.decode("utf-8", "replace").splitlines(keepends=True)
        newlines = new.decode("utf-8", "replace").splitlines(keepends=True)
        out.extend(difflib.unified_diff(oldlines, newlines, fromfile=f"a/{key}" if a else "/dev/null", tofile=f"b/{key}" if b else "/dev/null"))
    print("".join(out), end="")
    return 0
