"""Small, self-contained implementation of chezmoi's local init behavior."""
import os
import subprocess


def run(source, repo=None, ssh=False, branch=None, depth=None, guess=True):
    """Initialize *source*, optionally cloning a repository into it.

    Returns (stdout, stderr, status), matching command-module conventions.
    """
    source = os.path.abspath(os.path.expanduser(source))
    if repo:
        url = repo
        if guess and "://" not in repo and not os.path.exists(repo):
            if repo.startswith("sr.ht/"):
                userpart = repo[len("sr.ht/"):]
                if ssh:
                    url = "git@git.sr.ht:~" + userpart
                else:
                    url = "https://" + userpart.split("/", 1)[0] + "@git.sr.ht/~" + userpart.split("/", 1)[0]
                    if "/" in userpart:
                        url += "/" + userpart.split("/", 1)[1]
            elif "/" not in repo:
                if ssh:
                    url = "git@github.com:" + repo + "/dotfiles.git"
                else:
                    url = "https://" + repo + "@github.com/" + repo + "/dotfiles.git"
            elif ":" not in repo.split("/", 1)[0]:
                if ssh:
                    site, tail = repo.split("/", 1)
                    url = "git@" + site + ":" + tail + ".git"
                else:
                    url = "https://" + repo + ".git"
        if not os.path.exists(source):
            os.makedirs(os.path.dirname(source), exist_ok=True)
        cmd = ["git", "clone"]
        if depth is not None:
            cmd += ["--depth", str(depth)]
        if branch:
            cmd += ["--branch", branch]
        cmd += [url, source]
        p = subprocess.run(cmd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if p.returncode:
            msg = p.stderr.strip()
            if msg.startswith("fatal: "):
                msg = msg[7:]
            return "", "chezmoi: git: exit status " + str(p.returncode) + "\n", 1
        return "", "", 0
    os.makedirs(source, exist_ok=True)
    if not os.path.isdir(os.path.join(source, ".git")):
        p = subprocess.run(["git", "init", "--quiet", source], text=True,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if p.returncode:
            return "", "chezmoi: git: exit status " + str(p.returncode) + "\n", 1
    return "", "", 0
