import os

_PREFIXES = ("run_onchange_", "run_once_", "run_", "private_", "executable_",
             "readonly_", "symlink_", "encrypted_", "exact_", "create_",
             "modify_", "remove_", "once_", "before_", "after_",
             "on-change_", "empty_", "dot_")


def _decode_component(name):
    # Attribute prefixes can be stacked; dot_ is a filename transform.
    while True:
        for prefix in _PREFIXES:
            if name.startswith(prefix):
                name = name[len(prefix):]
                if prefix == "dot_":
                    name = "." + name
                break
        else:
            return name


def source_to_target(path, source, destination):
    source = os.path.abspath(os.path.expanduser(source))
