        rel = os.path.relpath(path, source)
    except ValueError:
        raise ValueError(f"{path}: not in {source}")
    if rel == os.pardir or rel.startswith(os.pardir + os.sep):
        raise ValueError(f"{path}: not in {source}")
    if rel == ".":
        raise ValueError(f"{path}: not a valid source path")
    components = rel.split(os.sep)
    if components[-1].endswith(".tmpl"):
