            prefix = 'executable_'
        elif (mode & 0o077) == 0:
            prefix = 'private_'
        elif not mode & 0o222:
            prefix = 'readonly_'
        if prefix:
            out[-1] = prefix + out[-1]
            name = os.path.join(*out)
    return name


