def _missing_template_error(template, name, data):
    """Return the Go-template style error for a missing dotted data field."""
    pattern = re.compile(r"{{\s*(?:if\s+)?(\.[A-Za-z_][\w.]*)")
    for match in pattern.finditer(template):
        expr = match.group(1)
        value = data
        missing = None
        for key in expr[1:].split("."):
