def decode_name(path):
    """Translate chezmoi source naming attributes into a target relative path."""
    parts = path.replace("\\", "/").split("/")
    out = []
    for part in parts:
        if part == ".chezmoiremove":
            continue
        prefixes = ("run_onchange_", "run_once_", "executable_", "readonly_",
                    "private_", "symlink_", "encrypted_", "empty_", "create_",
                    "modify_", "exact_", "remove_", "run_", "once_", "before_", "after_")
        while True:
            prefix = next((prefix for prefix in prefixes if part.startswith(prefix)), None)
            if prefix is None:
                break
            part = part[len(prefix):]
        if part.startswith("dot_"):
            part = "." + part[4:]
        if part.endswith(".tmpl"):
            part = part[:-5]
        out.append(part)
    return "/".join(out)


def _render(text, data):
    # Cover the common Go-template constructs used for dotfile templates.
    def lookup(expr):
        expr = expr.strip()
