            value = data
            for key in expr[1:].split("."):
                if not key:
                    continue
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    return None, False
            return value, True
        if expr in ("true", "false"):
            return expr == "true", True
        if expr in ("nil", "null"):
            return None, True
        if re.fullmatch(r"-?\d+", expr):
            return int(expr), True
        if re.fullmatch(r"-?\d+\.\d+", expr):
            return float(expr), True
        if len(expr) >= 2 and expr[0] == expr[-1] and expr[0] in ('"', "'"):
            return expr[1:-1], True
        try:
            words = shlex.split(expr)
        except ValueError:
            words = []
        if words:
            if words[0] == "list":
                return words[1:], True
            if words[0] == "dict" and len(words) % 2 == 1:
                return dict(zip(words[1::2], words[2::2])), True
            if words[0] == "not" and len(words) == 2:
                value, found = lookup(words[1])
                return (not value, found)
            if words[0] == "len" and len(words) == 2:
                value, found = lookup(words[1])
                try:
                    return len(value), found
                except TypeError:
                    return None, False
