            result = value
        for fn in bits[1:]:
            call = re.fullmatch(r"([A-Za-z][A-Za-z0-9_]*)\s+(.+)", fn)
            if call:
                name, arg_expr = call.groups()
                try:
                    arg_exprs = shlex.split(arg_expr)
                except ValueError:
