                    elif name == "trimSuffix":
                        result = stringify(result).removesuffix(stringify(arg))
                    elif name == "splitList":
                        result = stringify(result).split(stringify(arg))
                    elif name == "join":
                        result = stringify(arg).join(stringify(x) for x in result)
                    elif name == "hasPrefix":
                        result = stringify(result).startswith(stringify(arg))
                    elif name == "hasSuffix":
                        result = stringify(result).endswith(stringify(arg))
                    elif name == "contains":
                        result = stringify(arg) in stringify(result)
                    elif name == "replace" and len(values) >= 2:
                        result = stringify(result).replace(stringify(values[0]), stringify(values[1]))
                    elif name == "default":
                        if result in (None, False, "", 0, [], {}): result = arg
                    elif name == "quote":
                        result = json.dumps(stringify(result), ensure_ascii=False)
                    elif name == "toString":
                        result = stringify(result)
                    else:
                        return match.group(0)
                except (TypeError, ValueError, ZeroDivisionError):
                    return match.group(0)
                continue
            if fn == "upper":
                result = stringify(result).upper()
            elif fn == "lower":
                result = stringify(result).lower()
            elif fn == "title":
                result = stringify(result).title()
            elif fn in ("trim", "trimSpace"):
                result = stringify(result).strip()
            elif fn in ("toJson", "json"):
                result = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
            elif fn == "quote":
                result = json.dumps(stringify(result), ensure_ascii=False)
            elif fn == "squote":
                result = "'" + stringify(result).replace("'", "\\'") + "'"
            else:
                return match.group(0)
        return stringify(result)
    return re.sub(r"{{\s*([^{}]+?)\s*}}", sub, text)


def _ignored(relative, patterns):
    relative = relative.replace(os.sep, "/")
    for pat in patterns:
        pat = pat.strip()
        if not pat or pat.startswith("#"):
            continue
        while pat.startswith("./"):
            pat = pat[2:]
        pat = pat.lstrip("/")
        if (relative == pat or relative.endswith("/" + pat)
                or fnmatch.fnmatchcase(relative, pat)
                or fnmatch.fnmatchcase(os.path.basename(relative), pat)
                or relative.startswith(pat.rstrip("/") + "/")):
            return True
    return False


